const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
const lines = input.trim().split(/\s+/);

function factorial(n) {
    if (n === 0) return 1n;
    return BigInt(n) * factorial(n - 1);
}

lines.forEach(line => {
    if (line !== '') {
        console.log(factorial(parseInt(line)).toString());
    }
});
